DROP POLICY "quality questions readable" ON public.question_bank;
CREATE POLICY "quality questions readable" ON public.question_bank FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin') OR created_by=auth.uid() OR EXISTS(SELECT 1 FROM public.question_feedback f WHERE f.question_id=question_bank.id AND f.user_id=auth.uid() AND f.vote='report') OR (NOT quarantined AND grounding_type <> 'user_rag' AND ((status='active' AND source_origin IN ('official','ai_community')) OR (status='pending' AND source_origin='ai_ephemeral'))));
DROP POLICY "vote visible questions" ON public.question_feedback;
CREATE POLICY "vote visible questions" ON public.question_feedback FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.question_bank q WHERE q.id=question_id AND (q.created_by=auth.uid() OR (NOT q.quarantined AND q.grounding_type <> 'user_rag' AND ((q.status='active' AND q.source_origin IN ('official','ai_community')) OR (q.status='pending' AND q.source_origin='ai_ephemeral'))) OR public.has_role(auth.uid(),'admin'))));